public enum LampStates {
    OFF,
    DIM,
    ON
}

switch (system_state_) {
    case ON:
        lamp.setBrightness(1.0);
        break;
    case DIM:
        lamp.setBrightness(0.3);
        break;
    case OFF:
    default:
        lamp.setBrightness(0.0);
        break;
}

switch (system_state_) {
    case ARCADE:
        drive.arcadeDrive(OI.getForward(), OI.getTurn());
        break;
    case IDLE:
    default:
        drive.arcadeDrive(0.0, 0.0);
        break;
}
